    cancelNoteTool();closeCommandPalette();project=emptyProject();project.bpm=120;project.loop=false;selectedTrack=7;selectedNotes.clear();selectedNote=-1;currentFile=File();project.patterns[0].length=4;lane()={{0,1,60,.8f}};project.tracks[7].mixer.output=5;project.tracks[7].mixer.sidechain=0;project.tracks[7].volume=.43f;project.tracks[7].pan=.2f;project.tracks[7].send=.14f;undoStack.clear();redoStack.clear();effectClipboard.reset();publish();perform(stop);setSize(1180,800);resetLayout();showPane(effectsPane);selectedEffect=2;
    auto original=JSON::toString(projectToJson(project));check(moveEffect(2,-6)&&project.tracks[7].mixer.order==EffectOrder{2,0,1,3,4,5}&&selectedEffect==2&&undoStack.size()==1,"moving an effect to first preserves processor identity in one undo");perform(undoAction);check(JSON::toString(projectToJson(project))==original,"effect order Undo restores all original project state");perform(redoAction);check(project.tracks[7].mixer.order[0]==2,"effect order Redo restores new processing order");perform(undoAction);check(!moveEffect(0,-1)&&undoStack.empty(),"moving beyond the first slot is a history-free no-op");
