    auto entries=paletteEntries();int factories=0;for(const auto& entry:entries)if(entry.action==effectsFactoryRecall)++factories;check(factories==8&&!searchCommands(entries,"move selected effect earlier").empty()&&!searchCommands(entries,"paste effect chain").empty(),"Ctrl+P indexes factory chains, clipboard and ordering commands");
